class Proxy
  # Internal object returned from `method` for methods owned only by the target.
  # It behaves like a Method object for #call, but does not expose #super.
  class DelegatedMethod
    def initialize(proxy, name)
      @proxy = proxy
      @name = name
    end

    def call(*args, **kwargs, &block)
      @proxy.public_send(@name, *args, **kwargs, &block)
    end
  end

  def initialize(target)
    @target = target
  end

  # Make respond_to? aware of both the target's methods and Proxy's own methods.
  def respond_to?(name, include_private = false)
    super ||
      @target.respond_to?(name, include_private) ||
      (!include_private && @target.respond_to?(name, true))
  end

  # Make `method(:name)` work for target-only methods.
  def method(name)
    if respond_to?(name, false) && !super
      DelegatedMethod.new(self, name)
    else
      super
    end
  rescue NameError
    # Preserve normal Ruby behavior for unsupported method names.
    raise NameError, "undefined method `#{name}' for #<#{self.class}>"
  end

  # Forward any undefined public method to the target.
  def method_missing(name, *args, **kwargs, &block)
    if @target.respond_to?(name, false)
      @target.public_send(name, *args, **kwargs, &block)
    else
      raise NoMethodError,
            "undefined method `#{name}' for #<#{self.class}>"
    end
  end

  # Keep private-method support predictable for the target as well.
  def respond_to_missing?(name, include_private = false)
    @target.respond_to?(name, include_private) ||
      (!include_private && @target.respond_to?(name, true))
  end
end
