  end

  def store(key, value)
    @data[key] = value
  end

  def fetch(key, &block)
    if @data.key?(key)
      @data[key]
    elsif block
      block.call
    end
  end
end

class TallyingKeyStore < KeyStore
  attr_reader :hits, :misses

  def initialize
    super
    @hits = 0
    @misses = 0
  end

  def fetch(key, &block)
    if instance_variable_get(:@data).key?(key)
      @hits += 1
    else
      @misses += 1
    end

    super
  end
end
